module ComfyUI.Assets.SkillPacksPanelBpTD2B5rJsMap

let file = """{"version":3,"file":"SkillPacksPanel-BpTD2B5r.js","names":["$t","$t"],"sources":["../../src/platform/skills/composables/useSkillPacks.ts","../../src/platform/skills/composables/useSkillPackForm.ts","../../src/platform/skills/components/SkillPackFormDialog.vue","../../src/platform/skills/components/SkillPackFormDialog.vue","../../src/platform/skills/components/SkillPackListItem.vue","../../src/platform/skills/components/SkillPackListItem.vue","../../src/platform/skills/components/SkillPacksPanel.vue","../../src/platform/skills/components/SkillPacksPanel.vue"],"sourcesContent":["import { storeToRefs } from 'pinia'\nimport { ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useToast } from '@/components/ui/toast/toastStore'\n\nimport {\n  deleteSkillPack as deleteSkillPackApi,\n  SkillPacksApiError\n} from '../api/skillsApi'\nimport { useSkillPacksStore } from '../stores/skillPacksStore'\nimport type { SkillPack } from '../types'\n\nexport function useSkillPacks() {\n  const { t } = useI18n()\n  const toast = useToast()\n  const store = useSkillPacksStore()\n  const { packs, loading, hasLoaded } = storeToRefs(store)\n\n  const operatingPackName = ref<string | null>(null)\n\n  function reportUnexpected(error: unknown, errorType: string) {\n    reportError(error, { errorType, surface: 'agent' })\n    toast.error(t('g.error'), {\n      description:\n        error instanceof SkillPacksApiError\n          ? error.message\n          : t('g.unknownError')\n    })\n  }\n\n  async function fetchSkillPacks() {\n    try {\n      await store.fetchPacks()\n    } catch (error) {\n      reportUnexpected(error, 'error_fetching_agent_skill_packs')\n    }\n  }\n\n  /**\n   * Delete 404 means missing pack or disabled gate; re-list to distinguish them.\n   */\n  async function deleteSkillPack(pack: SkillPack) {\n    const requestScope = store.scope\n    operatingPackName.value = pack.name\n    try {\n      await deleteSkillPackApi(pack.name)\n      store.removePack(pack.name, requestScope)\n    } catch (error) {\n      if (!store.isCurrentScope(requestScope)) return\n      if (error instanceof SkillPacksApiError && error.status === 404) {\n        store.removePack(pack.name, requestScope)\n        await fetchSkillPacks()\n        return\n      }\n      reportUnexpected(error, 'error_deleting_agent_skill_pack')\n    } finally {\n      operatingPackName.value = null\n    }\n  }\n\n  return {\n    packs,\n    loading,\n    hasLoaded,\n    operatingPackName,\n    fetchSkillPacks,\n    deleteSkillPack\n  }\n}\n","import type { MaybeRefOrGetter } from 'vue'\nimport { computed, onScopeDispose, reactive, ref, toValue, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { reportError } from '@/platform/telemetry/reportError'\n\nimport { publishSkillPack, SkillPacksApiError } from '../api/skillsApi'\nimport { useSkillPacksStore } from '../stores/skillPacksStore'\nimport type { SkillPack } from '../types'\nimport {\n  CONTROL_CHARACTERS,\n  codePointLength,\n  MAX_DESCRIPTION_CODE_POINTS,\n  MAX_NAME_LENGTH,\n  PACK_NAME_PATTERN,\n  RESERVED_PACK_NAMES,\n  utf8ByteLength\n} from '../types'\n\ninterface UseSkillPackFormOptions {\n  pack?: MaybeRefOrGetter<SkillPack | undefined>\n  visible: { value: boolean }\n}\n\nexport function useSkillPackForm(options: UseSkillPackFormOptions) {\n  const { t } = useI18n()\n  const { pack: packRef, visible } = options\n  const store = useSkillPacksStore()\n\n  const loading = ref(false)\n  let formGeneration = 0\n  const fieldError = ref<string | null>(null)\n  // The server's 409 message names the configured limit and overage.\n  const budgetError = ref<string | null>(null)\n\n  const form = reactive({\n    name: '',\n    description: '',\n    body: ''\n  })\n\n  const errors = reactive({\n    name: '',\n    description: '',\n    body: ''\n  })\n\n  const isReplacing = computed(() =>\n    store.packs.some((existing) => existing.name === form.name.trim())\n  )\n\n  const bodyBytes = computed(() => utf8ByteLength(form.body))\n\n  function resetForm() {\n    const pack = toValue(packRef)\n    form.name = pack?.name ?? ''\n    form.description = pack?.description ?? ''\n    form.body = pack?.body ?? ''\n    errors.name = ''\n    errors.description = ''\n    errors.body = ''\n    fieldError.value = null\n    budgetError.value = null\n  }\n\n  resetForm()\n  watch(\n    () => visible.value,\n    () => formGeneration++,\n    { flush: 'sync' }\n  )\n  watch(\n    () => visible.value,\n    (isVisible) => {\n      if (isVisible) resetForm()\n    }\n  )\n  onScopeDispose(() => formGeneration++)\n\n  function validateName(): boolean {\n    const name = form.name.trim()\n    if (!name) {\n      errors.name = t('skillPacks.errors.nameRequired')\n      return false\n    }\n    if (name.length > MAX_NAME_LENGTH) {\n      errors.name = t('skillPacks.errors.nameTooLong', {\n        max: MAX_NAME_LENGTH\n      })\n      return false\n    }\n    if (!PACK_NAME_PATTERN.test(name)) {\n      errors.name = t('skillPacks.errors.nameCharset')\n      return false\n    }\n    if (RESERVED_PACK_NAMES.some((reserved) => reserved === name)) {\n      errors.name = t('skillPacks.errors.nameReserved', { name })\n      return false\n    }\n    if (!toValue(packRef) && isReplacing.value) {\n      errors.name = t('skillPacks.errors.nameAlreadyExists', { name })\n      return false\n    }\n    return true\n  }\n\n  function validateDescription(): boolean {\n    if (!form.description.trim()) {\n      errors.description = t('skillPacks.errors.descriptionRequired')\n      return false\n    }\n    if (CONTROL_CHARACTERS.test(form.description)) {\n      errors.description = t('skillPacks.errors.descriptionSingleLine')\n      return false\n    }\n    if (codePointLength(form.description) > MAX_DESCRIPTION_CODE_POINTS) {\n      errors.description = t('skillPacks.errors.descriptionTooLong', {\n        max: MAX_DESCRIPTION_CODE_POINTS\n      })\n      return false\n    }\n    return true\n  }\n\n  function validateBody(): boolean {\n    if (!form.body.trim()) {\n      errors.body = t('skillPacks.errors.bodyRequired')\n      return false\n    }\n    return true\n  }\n\n  function validate(): boolean {\n    errors.name = ''\n    errors.description = ''\n    errors.body = ''\n    fieldError.value = null\n    budgetError.value = null\n\n    if (!validateName() || !validateDescription() || !validateBody()) {\n      return false\n    }\n    return true\n  }\n\n  function handlePublishFailure(error: unknown, generation: number) {\n    if (error instanceof SkillPacksApiError && error.status === 404) {\n      store.markUnavailable()\n      if (generation === formGeneration) visible.value = false\n      return\n    }\n    if (!(error instanceof SkillPacksApiError)) {\n      reportError(error, {\n        errorType: 'error_publishing_agent_skill_pack',\n        surface: 'agent'\n      })\n    }\n    if (generation !== formGeneration) return\n    if (error instanceof SkillPacksApiError && error.status === 409) {\n      budgetError.value = error.message\n    } else if (error instanceof SkillPacksApiError) {\n      fieldError.value = error.message\n    } else {\n      fieldError.value = t('g.unknownError')\n    }\n  }\n\n  async function handleSubmit() {\n    if (loading.value || !visible.value) return\n    if (!validate()) return\n\n    const generation = formGeneration\n    const requestScope = store.scope\n    loading.value = true\n    try {\n      const saved = await publishSkillPack({\n        name: form.name.trim(),\n        description: form.description,\n        body: form.body\n      })\n      if (!store.isCurrentScope(requestScope)) return\n      store.upsertPack(saved, requestScope)\n      if (generation !== formGeneration) return\n      visible.value = false\n    } catch (error) {\n      if (!store.isCurrentScope(requestScope)) return\n      handlePublishFailure(error, generation)\n    } finally {\n      loading.value = false\n    }\n  }\n\n  return {\n    form,\n    errors,\n    loading,\n    fieldError,\n    budgetError,\n    bodyBytes,\n    handleSubmit\n  }\n}\n","<template>\n  <Dialog v-model:open=\"visible\">\n    <DialogPortal>\n      <DialogOverlay v-reka-z-index data-reka-nested-dialog-overlay />\n      <DialogContent v-reka-z-index size=\"md\" :aria-labelledby=\"titleId\">\n        <DialogHeader>\n          <DialogTitle :id=\"titleId\">\n            {{ pack ? $t('skillPacks.editPack') : $t('skillPacks.addPack') }}\n          </DialogTitle>\n          <DialogClose />\n        </DialogHeader>\n        <form\n          class=\"flex flex-col gap-4 px-4 py-2\"\n          @submit.prevent=\"handleSubmit\"\n        >\n          <div class=\"flex flex-col gap-1\">\n            <label :for=\"nameId\" class=\"text-sm font-medium\">\n              {{ $t('skillPacks.name') }}\n            </label>\n            <Input\n              :id=\"nameId\"\n              v-model=\"form.name\"\n              :placeholder=\"$t('skillPacks.namePlaceholder')\"\n              :disabled=\"pack !== undefined || loading\"\n              :aria-invalid=\"!!errors.name || undefined\"\n              :aria-describedby=\"`${nameId}-help`\"\n              :maxlength=\"MAX_NAME_LENGTH\"\n            />\n            <small\n              v-if=\"errors.name\"\n              :id=\"`${nameId}-help`\"\n              role=\"alert\"\n              class=\"text-destructive-background\"\n            >\n              {{ errors.name }}\n            </small>\n            <small v-else :id=\"`${nameId}-help`\" class=\"text-muted\">\n              {{ $t('skillPacks.nameHint') }}\n            </small>\n          </div>\n\n          <div class=\"flex flex-col gap-1\">\n            <label :for=\"descriptionId\" class=\"text-sm font-medium\">\n              {{ $t('skillPacks.triggerLine') }}\n            </label>\n            <Input\n              :id=\"descriptionId\"\n              v-model=\"form.description\"\n              :placeholder=\"$t('skillPacks.triggerLinePlaceholder')\"\n              :disabled=\"loading\"\n              :aria-invalid=\"!!errors.description || undefined\"\n              :aria-describedby=\"`${descriptionId}-help`\"\n            />\n            <small\n              v-if=\"errors.description\"\n              :id=\"`${descriptionId}-help`\"\n              role=\"alert\"\n              class=\"text-destructive-background\"\n            >\n              {{ errors.description }}\n            </small>\n            <small v-else :id=\"`${descriptionId}-help`\" class=\"text-muted\">\n              {{ $t('skillPacks.triggerLineHint') }}\n            </small>\n          </div>\n\n          <div class=\"flex flex-col gap-1\">\n            <label :for=\"bodyId\" class=\"text-sm font-medium\">\n              {{ $t('skillPacks.body') }}\n            </label>\n            <Textarea\n              :id=\"bodyId\"\n              v-model=\"form.body\"\n              class=\"min-h-48 font-mono\"\n              :placeholder=\"$t('skillPacks.bodyPlaceholder')\"\n              :disabled=\"loading\"\n              :aria-invalid=\"!!errors.body || undefined\"\n              :aria-describedby=\"`${bodyId}-help`\"\n            />\n            <small\n              v-if=\"errors.body\"\n              :id=\"`${bodyId}-help`\"\n              role=\"alert\"\n              class=\"text-destructive-background\"\n            >\n              {{ errors.body }}\n            </small>\n            <small v-else :id=\"`${bodyId}-help`\" class=\"text-muted\">{{\n              bodySizeLabel\n            }}</small>\n          </div>\n\n          <div\n            v-if=\"budgetError\"\n            data-testid=\"skill-pack-budget-error\"\n            role=\"alert\"\n            class=\"flex flex-col gap-1 rounded-lg border border-destructive-background p-3\"\n          >\n            <span class=\"text-sm font-medium text-destructive-background\">\n              {{ $t('skillPacks.atLimitTitle') }}\n            </span>\n            <span class=\"text-sm text-muted\">{{ budgetError }}</span>\n            <span class=\"text-sm text-muted\">\n              {{ $t('skillPacks.atLimitHint') }}\n            </span>\n          </div>\n\n          <span\n            v-else-if=\"fieldError\"\n            data-testid=\"skill-pack-field-error\"\n            role=\"alert\"\n            class=\"text-sm text-destructive-background\"\n          >\n            {{ fieldError }}\n          </span>\n\n          <div class=\"flex justify-end gap-2 py-2\">\n            <Button variant=\"secondary\" type=\"button\" @click=\"visible = false\">\n              {{ $t('g.cancel') }}\n            </Button>\n            <Button type=\"submit\" :loading=\"loading\">\n              {{ $t('skillPacks.publish') }}\n            </Button>\n          </div>\n        </form>\n      </DialogContent>\n    </DialogPortal>\n  </Dialog>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, useId } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { vRekaZIndex } from '@/components/dialog/vRekaZIndex'\nimport Button from '@/components/ui/button/Button.vue'\nimport Dialog from '@/components/ui/dialog/Dialog.vue'\nimport DialogClose from '@/components/ui/dialog/DialogClose.vue'\nimport DialogContent from '@/components/ui/dialog/DialogContent.vue'\nimport DialogHeader from '@/components/ui/dialog/DialogHeader.vue'\nimport DialogOverlay from '@/components/ui/dialog/DialogOverlay.vue'\nimport DialogPortal from '@/components/ui/dialog/DialogPortal.vue'\nimport DialogTitle from '@/components/ui/dialog/DialogTitle.vue'\nimport Input from '@/components/ui/input/Input.vue'\nimport Textarea from '@/components/ui/textarea/Textarea.vue'\n\nimport { useSkillPackForm } from '../composables/useSkillPackForm'\nimport type { SkillPack } from '../types'\nimport { MAX_NAME_LENGTH } from '../types'\n\nconst { pack } = defineProps<{\n  pack?: SkillPack\n}>()\n\nconst visible = defineModel<boolean>('visible', { default: false })\n\nconst { t } = useI18n()\nconst titleId = useId()\nconst nameId = useId()\nconst descriptionId = useId()\nconst bodyId = useId()\n\nconst {\n  form,\n  errors,\n  loading,\n  fieldError,\n  budgetError,\n  bodyBytes,\n  handleSubmit\n} = useSkillPackForm({\n  pack: () => pack,\n  visible\n})\n\nconst bodySizeLabel = computed(() =>\n  t('skillPacks.bodySize', {\n    bytes: bodyBytes.value\n  })\n)\n</script>\n","<template>\n  <Dialog v-model:open=\"visible\">\n    <DialogPortal>\n      <DialogOverlay v-reka-z-index data-reka-nested-dialog-overlay />\n      <DialogContent v-reka-z-index size=\"md\" :aria-labelledby=\"titleId\">\n        <DialogHeader>\n          <DialogTitle :id=\"titleId\">\n            {{ pack ? $t('skillPacks.editPack') : $t('skillPacks.addPack') }}\n          </DialogTitle>\n          <DialogClose />\n        </DialogHeader>\n        <form\n          class=\"flex flex-col gap-4 px-4 py-2\"\n          @submit.prevent=\"handleSubmit\"\n        >\n          <div class=\"flex flex-col gap-1\">\n            <label :for=\"nameId\" class=\"text-sm font-medium\">\n              {{ $t('skillPacks.name') }}\n            </label>\n            <Input\n              :id=\"nameId\"\n              v-model=\"form.name\"\n              :placeholder=\"$t('skillPacks.namePlaceholder')\"\n              :disabled=\"pack !== undefined || loading\"\n              :aria-invalid=\"!!errors.name || undefined\"\n              :aria-describedby=\"`${nameId}-help`\"\n              :maxlength=\"MAX_NAME_LENGTH\"\n            />\n            <small\n              v-if=\"errors.name\"\n              :id=\"`${nameId}-help`\"\n              role=\"alert\"\n              class=\"text-destructive-background\"\n            >\n              {{ errors.name }}\n            </small>\n            <small v-else :id=\"`${nameId}-help`\" class=\"text-muted\">\n              {{ $t('skillPacks.nameHint') }}\n            </small>\n          </div>\n\n          <div class=\"flex flex-col gap-1\">\n            <label :for=\"descriptionId\" class=\"text-sm font-medium\">\n              {{ $t('skillPacks.triggerLine') }}\n            </label>\n            <Input\n              :id=\"descriptionId\"\n              v-model=\"form.description\"\n              :placeholder=\"$t('skillPacks.triggerLinePlaceholder')\"\n              :disabled=\"loading\"\n              :aria-invalid=\"!!errors.description || undefined\"\n              :aria-describedby=\"`${descriptionId}-help`\"\n            />\n            <small\n              v-if=\"errors.description\"\n              :id=\"`${descriptionId}-help`\"\n              role=\"alert\"\n              class=\"text-destructive-background\"\n            >\n              {{ errors.description }}\n            </small>\n            <small v-else :id=\"`${descriptionId}-help`\" class=\"text-muted\">\n              {{ $t('skillPacks.triggerLineHint') }}\n            </small>\n          </div>\n\n          <div class=\"flex flex-col gap-1\">\n            <label :for=\"bodyId\" class=\"text-sm font-medium\">\n              {{ $t('skillPacks.body') }}\n            </label>\n            <Textarea\n              :id=\"bodyId\"\n              v-model=\"form.body\"\n              class=\"min-h-48 font-mono\"\n              :placeholder=\"$t('skillPacks.bodyPlaceholder')\"\n              :disabled=\"loading\"\n              :aria-invalid=\"!!errors.body || undefined\"\n              :aria-describedby=\"`${bodyId}-help`\"\n            />\n            <small\n              v-if=\"errors.body\"\n              :id=\"`${bodyId}-help`\"\n              role=\"alert\"\n              class=\"text-destructive-background\"\n            >\n              {{ errors.body }}\n            </small>\n            <small v-else :id=\"`${bodyId}-help`\" class=\"text-muted\">{{\n              bodySizeLabel\n            }}</small>\n          </div>\n\n          <div\n            v-if=\"budgetError\"\n            data-testid=\"skill-pack-budget-error\"\n            role=\"alert\"\n            class=\"flex flex-col gap-1 rounded-lg border border-destructive-background p-3\"\n          >\n            <span class=\"text-sm font-medium text-destructive-background\">\n              {{ $t('skillPacks.atLimitTitle') }}\n            </span>\n            <span class=\"text-sm text-muted\">{{ budgetError }}</span>\n            <span class=\"text-sm text-muted\">\n              {{ $t('skillPacks.atLimitHint') }}\n            </span>\n          </div>\n\n          <span\n            v-else-if=\"fieldError\"\n            data-testid=\"skill-pack-field-error\"\n            role=\"alert\"\n            class=\"text-sm text-destructive-background\"\n          >\n            {{ fieldError }}\n          </span>\n\n          <div class=\"flex justify-end gap-2 py-2\">\n            <Button variant=\"secondary\" type=\"button\" @click=\"visible = false\">\n              {{ $t('g.cancel') }}\n            </Button>\n            <Button type=\"submit\" :loading=\"loading\">\n              {{ $t('skillPacks.publish') }}\n            </Button>\n          </div>\n        </form>\n      </DialogContent>\n    </DialogPortal>\n  </Dialog>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, useId } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { vRekaZIndex } from '@/components/dialog/vRekaZIndex'\nimport Button from '@/components/ui/button/Button.vue'\nimport Dialog from '@/components/ui/dialog/Dialog.vue'\nimport DialogClose from '@/components/ui/dialog/DialogClose.vue'\nimport DialogContent from '@/components/ui/dialog/DialogContent.vue'\nimport DialogHeader from '@/components/ui/dialog/DialogHeader.vue'\nimport DialogOverlay from '@/components/ui/dialog/DialogOverlay.vue'\nimport DialogPortal from '@/components/ui/dialog/DialogPortal.vue'\nimport DialogTitle from '@/components/ui/dialog/DialogTitle.vue'\nimport Input from '@/components/ui/input/Input.vue'\nimport Textarea from '@/components/ui/textarea/Textarea.vue'\n\nimport { useSkillPackForm } from '../composables/useSkillPackForm'\nimport type { SkillPack } from '../types'\nimport { MAX_NAME_LENGTH } from '../types'\n\nconst { pack } = defineProps<{\n  pack?: SkillPack\n}>()\n\nconst visible = defineModel<boolean>('visible', { default: false })\n\nconst { t } = useI18n()\nconst titleId = useId()\nconst nameId = useId()\nconst descriptionId = useId()\nconst bodyId = useId()\n\nconst {\n  form,\n  errors,\n  loading,\n  fieldError,\n  budgetError,\n  bodyBytes,\n  handleSubmit\n} = useSkillPackForm({\n  pack: () => pack,\n  visible\n})\n\nconst bodySizeLabel = computed(() =>\n  t('skillPacks.bodySize', {\n    bytes: bodyBytes.value\n  })\n)\n</script>\n","<template>\n  <div class=\"group relative rounded-lg border border-border-default\">\n    <Button\n      variant=\"textonly\"\n      size=\"unset\"\n      class=\"flex w-full min-w-0 flex-col items-start gap-1 rounded-lg p-4 pr-24 text-left font-normal whitespace-normal hover:bg-transparent\"\n      :aria-label=\"pack.name\"\n      :aria-describedby=\"descriptionId\"\n      :disabled=\"disabled || loading\"\n      @click=\"emit('edit')\"\n    >\n      <span class=\"w-full truncate font-medium text-base-foreground\">\n        {{ pack.name }}\n      </span>\n      <span :id=\"descriptionId\" class=\"line-clamp-2 text-sm text-muted\">\n        {{ pack.description }}\n      </span>\n      <span class=\"text-xs text-muted\">{{ sizeLabel }}</span>\n    </Button>\n    <div class=\"absolute top-4 right-4\">\n      <i\n        v-if=\"loading\"\n        class=\"icon-[lucide--loader-circle] size-4 animate-spin text-muted\"\n      />\n      <div\n        v-else\n        :class=\"\n          cn(\n            'pointer-events-none flex items-center gap-2 opacity-0 transition-opacity group-hover:pointer-events-auto group-hover:opacity-100 touch:pointer-events-auto touch:opacity-100',\n            keyboardNavigation &&\n              'group-has-focus-v